using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using AstroGateway.MarsEnvironment;
namespace AstroGateway.VisualPolish {public class PolishBenchmark:MonoBehaviour {
 public string output;IEnumerator Start(){var e=FindAnyObjectByType<EnvironmentPresentation>();while(!e.game.initialized)yield return null;e.game.testing=true;var lines=new List<string>{"Actual Unity Editor batch Play Mode Game View frame cadence. Not interactive Editor, GPU-only time, or Android performance.","Unity="+Application.unityVersion+" GPU="+SystemInfo.graphicsDeviceName+" API="+SystemInfo.graphicsDeviceType+" framebuffer="+Screen.width+"x"+Screen.height,"Camera=fixed astronaut spawn; weather=clear; no capture during sample; no intentional sleep; 2-second warmup then >=5 seconds sampling per preset."};for(int q=0;q<4;q++){e.ApplyQuality(q);yield return new WaitForSecondsRealtime(2);var samples=new List<double>();double start=Time.realtimeSinceStartupAsDouble,prev=start;while(Time.realtimeSinceStartupAsDouble-start<5){yield return null;double now=Time.realtimeSinceStartupAsDouble;samples.Add((now-prev)*1000);prev=now;}samples.Sort();double avg=samples.Average();lines.Add(new[]{"Low","Medium","High","Desktop"}[q]+": frames="+samples.Count+" average_ms="+avg.ToString("F2")+" effective_fps="+(1000/avg).ToString("F2")+" p95_ms="+samples[Math.Min(samples.Count-1,(int)(samples.Count*.95))].ToString("F2")+" "+e.Readback());}lines.Add("CPU/GPU timing, drawn batches, thermal state: not instrumented; batch cadence is not an improvement claim.");File.WriteAllLines(output,lines);
#if UNITY_EDITOR
UnityEditor.EditorApplication.Exit(0);
#endif
}}}
